const f = $('Find Customer').item.json;
const ctx = $('Load Customer Context').item.json;
const prev = $('Format Email Chain').item.json;
function list(arr, fn) { if (!arr || !arr.length) return 'none'; return arr.map(fn).join('; '); }
let contextText = '';
const mc = Number(f.match_count || 0);
if (mc === 1 && f.customer) {
  const c = f.customer;
  contextText = 'Customer: ' + c.name + ' <' + c.email + '> (matched via ' + c.via + ')\n';
  contextText += 'Contacts: ' + list(ctx.contacts, x => x.name + ' <' + x.email + '>' + (x.phone ? ' ' + x.phone : '')) + '\n';
  contextText += 'Sites: ' + list(ctx.sites, x => x.name + ' (' + x.address + ')') + '\n';
  contextText += 'Equipment: ' + list(ctx.equipment, x => x.name + (x.model ? ' model ' + x.model : '') + (x.serial_number ? ' S/N ' + x.serial_number : '') + (x.battery_configuration ? ' [' + x.battery_configuration + ']' : '')) + '\n';
  contextText += 'Recent purchases: ' + list(ctx.purchases, x => x.name + ' on ' + x.occurred_on + (x.amount != null ? ' $' + x.amount : '')) + '\n';
  contextText += 'Recent services: ' + list(ctx.services, x => x.name + ' on ' + x.occurred_on + (x.notes ? ' - ' + x.notes : ''));
} else if (mc > 1) {
  contextText = 'WARNING: multiple CRM customers match this sender email. Do not reference any specific account details; answer generally and note the account needs manual review.';
}
return [{ json: { contextText, customerMatched: mc === 1, matchCount: mc, subject: prev.subject, sender: prev.sender, threadText: prev.threadText, messageId: prev.messageId } }];

const items = $input.all();
const sorted = items.slice().sort((a, b) => new Date(a.json.receivedDateTime) - new Date(b.json.receivedDateTime));
let thread = "";
for (const i of sorted) {
  const from = (i.json.from && i.json.from.emailAddress && i.json.from.emailAddress.address) || "unknown";
  const when = i.json.receivedDateTime || "";
  const body = (i.json.body && i.json.body.content) || i.json.bodyPreview || "";
  const sep = thread ? "\n\n---\n\n" : "";
  thread += sep + "From: " + from + "\nDate: " + when + "\n" + body;
}
const latest = items[items.length - 1].json;
return [{
  json: {
    threadText: thread,
    subject: latest.subject || "",
    sender: (latest.from && latest.from.emailAddress && latest.from.emailAddress.address) || "",
    messageId: $('New Outlook Email').first().json.id,
  },
}];

const stored = $('Check Stored Thread').item.json.messages || [];
const trig = $('New Outlook Email').first().json;
const items = stored.map(m => ({ json: {
  subject: trig.subject || '',
  receivedDateTime: m.occurred_at,
  body: { content: m.body_text || '' },
  bodyPreview: (m.body_text || '').slice(0, 255),
  from: { emailAddress: { address: m.sender || '' } },
}}));
const alreadyStored = stored.some(m => m.provider_key === trig.id);
if (!alreadyStored) {
  items.push({ json: {
    subject: trig.subject || '',
    receivedDateTime: trig.receivedDateTime,
    body: trig.body || { content: trig.bodyPreview || '' },
    bodyPreview: trig.bodyPreview || '',
    from: trig.from,
  }});
}
return items;
